#define SIMRIGSTATE_F_TEMP_C ((SimRigState_mask_t)1u << 3)  /* temp_c (double) */
#define SIMRIGSTATE_F_UPTIME_MS ((SimRigState_mask_t)1u << 4)  /* uptime_ms (int64) */
#define SIMRIGSTATE_F_LED_ON ((SimRigState_mask_t)1u << 5)  /* led_on (bool) */
#define SIMRIGSTATE_F_ALL ((SimRigState_mask_t)0x3fu)

