    uint8_t pre;
    SimRigState_mask_t m;
    uint16_t n, cp;
    (void)n; (void)cp;
    if (len < SIMRIGSTATE_PRELUDE_BYTES) return -1;
    pre = (uint8_t)((uint8_t)p[0]);
    p += 1;
    m = (SimRigState_mask_t)(pre >> 0) & SIMRIGSTATE_F_ALL;
    if (present) *present = m;
